import{_ as t,o as r,c as o,a7 as a}from"./chunks/framework.C4ZIv4ii.js";const s="/falconcms/screenshots/wholesale-product-tab.webp",i="/falconcms/screenshots/wholesale-prices.webp",m=JSON.parse('{"title":"Prices","description":"","frontmatter":{},"headers":[],"relativePath":"wholesale/pricing.md","filePath":"wholesale/pricing.md","lastUpdated":1792170474000}'),n={name:"wholesale/pricing.md"};function c(l,e,h,d,p,u){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="prices" tabindex="-1">Prices <a class="header-anchor" href="#prices" aria-label="Permalink to &quot;Prices&quot;">​</a></h1><p>Wholesale prices can come from five places, from the most specific to the most general. You can use one of them or all of them: price your best sellers one by one, give a whole category a discount, and let the level&#39;s discount cover everything else.</p><hr><h2 id="which-price-applies" tabindex="-1">Which price applies <a class="header-anchor" href="#which-price-applies" aria-label="Permalink to &quot;Which price applies&quot;">​</a></h2><p>For a signed-in, approved wholesale customer, the first of these that has a value wins:</p><table tabindex="0"><thead><tr><th>#</th><th>Source</th><th>Where you set it</th><th>Tiers on top?</th></tr></thead><tbody><tr><td>1</td><td>An accepted <strong>quote</strong> (in the cart)</td><td>Wholesale → Quotes</td><td>No</td></tr><tr><td>2</td><td>A <strong>contract price</strong> for their company</td><td>Wholesale → Customers → customer → Contract prices</td><td>No</td></tr><tr><td>3</td><td>The <strong>variation&#39;s</strong> wholesale price for their level</td><td>Product → Variations</td><td>Yes</td></tr><tr><td>4</td><td>The <strong>product&#39;s</strong> wholesale price for their level (simple products)</td><td>Product → Wholesale</td><td>Yes</td></tr><tr><td>5</td><td>The biggest <strong>category discount</strong> for their level, off the regular price</td><td>Product category screen</td><td>Yes</td></tr><tr><td>6</td><td>Their <strong>level&#39;s discount</strong>, off the regular price</td><td>Wholesale → Levels</td><td>Yes</td></tr></tbody></table><p>Then the <strong>quantity tier</strong> the cart quantity reaches is applied, if the product has tiers (rows 3–6 only). When none of these gives a price, the customer pays retail.</p><p>On the storefront the retail price is shown struck through next to the wholesale price. The same price goes into the cart, the checkout and the order, and the order records the customer&#39;s level.</p><div class="tip custom-block"><p class="custom-block-title">Never more than retail</p><p>With <strong>Never charge more than retail</strong> on (the default, in Settings), a wholesale customer never pays more than a retail sale price: when a retail sale is cheaper than their wholesale price, they pay the sale price. This covers contract prices too.</p></div><hr><h2 id="a-product-s-wholesale-prices" tabindex="-1">A product&#39;s wholesale prices <a class="header-anchor" href="#a-product-s-wholesale-prices" aria-label="Permalink to &quot;A product&#39;s wholesale prices&quot;">​</a></h2><p>Open a product and click the <strong>Wholesale</strong> tab in <strong>Product Data</strong>.</p><p><img src="'+s+`" alt="The Wholesale tab in the product editor"></p><p><em>A price for each level, two quantity tiers, who can see the product, a minimum quantity and a pack size.</em></p><table tabindex="0"><thead><tr><th>Field</th><th>What it does</th></tr></thead><tbody><tr><td><strong>{Level} price</strong></td><td>One box per level. Leave it empty to use the category or level discount (the box shows which, as a placeholder).</td></tr><tr><td><strong>Quantity tiers</strong></td><td>Cheaper prices for bigger quantities; see <a href="#quantity-tiers">Quantity tiers</a></td></tr><tr><td><strong>Who can see it</strong></td><td>Everyone, wholesale customers only, or retail customers only; see <a href="#who-sees-which-products">Who sees which products</a></td></tr><tr><td><strong>Minimum quantity</strong></td><td>The fewest a wholesale customer can order of this product</td></tr><tr><td><strong>Sold in packs of</strong></td><td>Wholesale quantities must be a multiple of this (12, say), per cart line</td></tr></tbody></table><p>For a <strong>variable product</strong> the prices per level are set on each variation instead: open <strong>Variations</strong>, and each variation has a <strong>Wholesale price</strong> box per level. A variation without one gets the category or level discount.</p><p>The ordering rules (minimum, packs, maximum) are explained on <a href="/falconcms/wholesale/ordering.html#ordering-rules">Ordering &amp; Checkout</a>.</p><hr><h2 id="quantity-tiers" tabindex="-1">Quantity tiers <a class="header-anchor" href="#quantity-tiers" aria-label="Permalink to &quot;Quantity tiers&quot;">​</a></h2><p>Tiers make a product cheaper when a wholesale customer buys more. Each tier is a range and a price:</p><ul><li><strong>Levels</strong> — all levels, or one level only. When tiers overlap, one made for the customer&#39;s level wins over an &quot;all levels&quot; one.</li><li><strong>From … to … pieces</strong> — leave <strong>to</strong> empty for no upper limit.</li><li><strong>% off</strong> the customer&#39;s wholesale price (or the retail price, when there is none), or <strong>price each</strong>, a fixed price that replaces it.</li></ul><p>Tiers sort themselves, smallest first. The <strong>duplicate</strong> button copies a tier and starts the copy where the original ends, so building a ladder is quick: 10–49 at 5% off, duplicate, 50–200 at 10%.</p><p><strong>The last tier&#39;s &quot;to&quot; is the most a wholesale customer can order</strong> of the product. The quantity box stops there and the cart refuses more. Leave it empty for no maximum.</p><p>On the product page the tiers are a <strong>picker</strong> tied to the quantity box: choosing a tier puts its quantity in the box, and typing a quantity (or using + and −) selects the tier it falls in. The tier a line is priced at is shown with it in the cart, mini-cart, checkout, order confirmation, the admin order, invoices and the order email.</p><div class="warning custom-block"><p class="custom-block-title">Variable products: percentages only</p><p>On a variable product, tiers can only be percentages. One fixed price would be wrong for options priced differently; set each option&#39;s own wholesale price in Variations.</p></div><h3 id="mix-match" tabindex="-1">Mix &amp; match <a class="header-anchor" href="#mix-match" aria-label="Permalink to &quot;Mix &amp; match&quot;">​</a></h3><p>The variations of one product always count together for its tiers: 10 red and 10 blue reach a 20+ tier.</p><p>To let <strong>different products</strong> count together, tick <strong>Mix &amp; match</strong> on a product category. In the cart, any 50 products of that category reach a 50+ tier (each product still uses its own tiers). The cart line says how many were counted together, and the product page says which categories mix.</p><hr><h2 id="category-discounts" tabindex="-1">Category discounts <a class="header-anchor" href="#category-discounts" aria-label="Permalink to &quot;Category discounts&quot;">​</a></h2><p>Edit a product category and you&#39;ll find <strong>Wholesale discount</strong>: a percentage off for each level. It applies to every product in the category that has no wholesale price of its own. A product in several categories gets the biggest discount.</p><hr><h2 id="contract-prices" tabindex="-1">Contract prices <a class="header-anchor" href="#contract-prices" aria-label="Permalink to &quot;Contract prices&quot;">​</a></h2><p>A contract price is a price for <strong>one company</strong>, agreed with them, whatever its level. Add it on the customer&#39;s screen under <strong>Contract prices</strong>: a <strong>SKU or product ID</strong> and a <strong>price each</strong>. A variation&#39;s SKU prices just that option; the product&#39;s SKU or ID prices every option. Saving the same product again changes its price.</p><p>A contract price wins over level, category and tier prices, and everyone in the company gets it.</p><hr><h2 id="who-sees-which-products" tabindex="-1">Who sees which products <a class="header-anchor" href="#who-sees-which-products" aria-label="Permalink to &quot;Who sees which products&quot;">​</a></h2><p>Each product&#39;s <strong>Who can see it</strong> setting:</p><table tabindex="0"><thead><tr><th>Option</th><th>Effect</th></tr></thead><tbody><tr><td><strong>Everyone</strong></td><td>The default</td></tr><tr><td><strong>Wholesale customers only</strong></td><td>Hidden from everyone else</td></tr><tr><td><strong>Retail customers only</strong></td><td>Hidden from wholesale customers</td></tr></tbody></table><p>A hidden product is left out of the shop, search, related products and upsells. Its page answers &quot;not found&quot; and it cannot be bought.</p><p>For page content, wrap anything in a shortcode:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[falcon_wholesale_only]Trade terms: 30 days net.[/falcon_wholesale_only]</span></span>
<span class="line"><span>[falcon_retail_only]Free returns within 14 days.[/falcon_retail_only]</span></span></code></pre></div><p><code>[falcon_wholesale_only]</code> shows nothing to others, or a message with <code>message=&quot;…&quot;</code>, with a sign-in link when you add <code>login=&quot;yes&quot;</code>.</p><hr><h2 id="who-sees-prices" tabindex="-1">Who sees prices <a class="header-anchor" href="#who-sees-prices" aria-label="Permalink to &quot;Who sees prices&quot;">​</a></h2><p><strong>Settings → Who sees prices</strong> decides whether prices are public:</p><table tabindex="0"><thead><tr><th>Option</th><th>Effect</th></tr></thead><tbody><tr><td><strong>Everyone</strong></td><td>A normal shop</td></tr><tr><td><strong>Signed-in customers only</strong></td><td>Guests see &quot;Log in to see prices&quot; instead of the price and cannot add to the cart</td></tr><tr><td><strong>Wholesale customers only (B2B shop)</strong></td><td>Only approved trade customers see prices and can buy; others see &quot;Log in to buy&quot; or &quot;Apply for wholesale&quot;</td></tr></tbody></table><p>Hidden prices are also left out of what search engines read.</p><p>To close the <strong>whole storefront</strong>, use <strong>Private store</strong> instead (see <a href="/falconcms/wholesale/settings.html#private-store">Settings</a>).</p><hr><h2 id="price-filter-and-sort" tabindex="-1">Price filter and sort <a class="header-anchor" href="#price-filter-and-sort" aria-label="Permalink to &quot;Price filter and sort&quot;">​</a></h2><p>The shop&#39;s price filter, price sort and price band show what the customer&#39;s level pays, not retail. They read a <strong>price index</strong>, which is updated when a product, category or level is saved, every night, and from <strong>Settings → Price index → Rebuild the price index</strong>.</p><hr><h2 id="prices-in-a-spreadsheet" tabindex="-1">Prices in a spreadsheet <a class="header-anchor" href="#prices-in-a-spreadsheet" aria-label="Permalink to &quot;Prices in a spreadsheet&quot;">​</a></h2><p><strong>Wholesale → Import / export</strong> handles every wholesale price at once.</p><p><img src="`+i+'" alt="Wholesale prices import and export"></p><p><em>Download every product and variation as CSV, edit it in Excel, and import it back.</em></p><ol><li><strong>Download CSV.</strong> Every product and variation, with its retail price, its wholesale price for each level (<code>price_wholesale</code>, <code>price_dealer</code>…), the minimum quantity, the pack size and who can see it.</li><li><strong>Edit</strong> it in a spreadsheet.</li><li><strong>Import CSV.</strong></li></ol><p>How the file is read:</p><ul><li>Rows are matched by <strong>SKU</strong>. Products without a SKU cannot be imported; give them one first.</li><li>An <strong>empty cell removes</strong> that wholesale price. A column you delete is left as it is in the shop.</li><li><code>min_qty</code>, <code>qty_step</code> and <code>visibility</code> (<code>all</code>, <code>wholesale</code> or <code>retail</code>) are read from product rows only; on variation rows they stay empty.</li><li><code>product</code>, <code>option</code> and <code>retail_price</code> are for reading only.</li><li>Quantity tiers are set in the product editor and are not part of the file.</li></ul>',60)])])}const y=t(n,[["render",c]]);export{m as __pageData,y as default};
